import { RuleFrontmatter } from "./parseMarkdownRule";

export const RULE_FILE_EXTENSION = "md";

export interface CreateRuleMarkdownOptions {
  description?: RuleFrontmatter["description"];
  globs?: RuleFrontmatter["globs"];
  alwaysApply?: RuleFrontmatter["alwaysApply"];
}

/**
 * Sanitizes a rule name for use in a filename.
 * - Lowercases the name
 * - Removes non-alphanumeric characters (keeping spaces and hyphens)
 * - Replaces runs of whitespace with a single hyphen
 * - Trims leading/trailing dashes
 */
export function sanitizeRuleName(ruleName: string): string {
  return ruleName
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/**
 * Constructs the path for a rule file within a workspace:
 * `{workspaceDir}/.continue/rules/{sanitized-name}.md`
 */
export function createRuleFilePath(
  workspaceDir: string,
  ruleName: string,
): string {
  const sanitizedName = sanitizeRuleName(ruleName);
  return joinPathsToUri(
    workspaceDir,
    ".continue",
    "rules",
    `${sanitizedName}.${RULE_FILE_EXTENSION}`,
  );
}

/**
 * Combines YAML frontmatter with markdown content.
 * Produces output parseable by `parseMarkdownRule`.
 */
export function createMarkdownWithFrontmatter(
  frontmatter: RuleFrontmatter,
  markdown: string,
): string {
  const frontmatterYaml = YAML.stringify(frontmatter).trim();
  return `---\n${frontmatterYaml}\n---\n\n${markdown}`;
}

/**
 * Generates the markdown content for a rule, including any provided
 * frontmatter fields.
 */
export function createRuleMarkdown(
  name: string,
  ruleContent: string,
  options: CreateRuleMarkdownOptions = {},
): string {
  const frontmatter: RuleFrontmatter = {};

  if (options.description) {
    frontmatter.description = options.description.trim();
  }

  if (options.globs) {
    frontmatter.globs =
      typeof options.globs === "string" ? options.globs.trim() : options.globs;
  }

  // Only include alwaysApply when it is explicitly set to false
  if (options.alwaysApply === false) {
    frontmatter.alwaysApply = options.alwaysApply;
  }

  const markdown = `# ${name}\n\n${ruleContent}`;

  return createMarkdownWithFrontmatter(frontmatter, markdown);
}
